import{_ as p,c as e,o as t,ah as r}from"./chunks/framework.Dnh4IO1K.js";const d=JSON.parse('{"title":"21、【噬嗑】 震下離上","description":"周易闡真 - 21、【噬嗑】 震下離上","frontmatter":{"title":"21、【噬嗑】 震下離上","description":"周易闡真 - 21、【噬嗑】 震下離上"},"headers":[],"relativePath":"classics/chanzhen/022.md","filePath":"classics/chanzhen/022.md"}'),s={name:"classics/chanzhen/022.md"};function n(c,a,i,o,l,h){return t(),e("div",null,[...a[0]||(a[0]=[r('<blockquote><p>彖曰：頤中有物曰噬嗑。噬嗑而亨，剛柔分，動而明，雷電合而章。柔得中而上行，雖不當位，利用獄也。</p></blockquote><h1 id="_21、【噬嗑】-震下離上" tabindex="-1">21、【噬嗑】 震下離上 <a class="header-anchor" href="#_21、【噬嗑】-震下離上" aria-label="Permalink to “21、【噬嗑】 震下離上”">​</a></h1><p>初九：屨校滅趾，無咎。</p><p>六二：噬膚滅鼻，無咎。</p><p>六三：噬臘肉，遇毒，小吝，無咎。</p><p>九四：噬乾胏，得金矢。利艱貞，吉。</p><p>六五：噬乾肉，得黃金。貞厲，無咎。</p><p>上九：何校滅耳，兇。</p><h2 id="孔易闡真-​" tabindex="-1">孔易闡真 ​ <a class="header-anchor" href="#孔易闡真-​" aria-label="Permalink to “孔易闡真 ​”">​</a></h2><p>大象：雷電，噬嗑，先王以明罰敕法。</p><p>噬嗑者，口食物而合也。上離火，下震雷，隨雷之火為電，是雷電一處。雷以震物，電以照物，刑中有德，殺中有生，如口食物必合，動不妄動，動而必明其滋味，此噬嗑之象也。</p><p>先王有見於此，知強暴兇惡之徒，多蹈於死地，而莫可逃者，皆由不知有罰法也。以是治律條，豫明輕重大小之罰，使人知其罪不可犯。果有不服王化，明知故犯，量其輕重大小之罪，敕其一定之法，使人知法不容逃。先明以示之，後威以刑之，生殺分明，刑德兩用。在執法者不濫刑，在受法者甘於死，彼此無間，噬而嗑矣。罰也，法也。皆先王以明敕之，無非為天地立心，為生民立命也。凡用法者須當效先王，先明後行，庶不誤傷其性命矣。彼世之妄想成道者，不能先窮其理，冒然下手，入於旁門曲學，著空執相，欲求長生，反而促死，其即先王之罪人，亦系嗑而未噬，空空無物，何益於事乎?</p><h2 id="悟元子註解-​" tabindex="-1">悟元子註解 ​ <a class="header-anchor" href="#悟元子註解-​" aria-label="Permalink to “悟元子註解 ​”">​</a></h2><p>噬，音食。嗑，音合。膚，音福。乾，音幹。胏，音子。</p><p>噬者，食也；嗑者，合也，食物口合之義。卦體上下二陽象唇，三陰象齒，中一陽象口中有物。又卦德上離明，下震動，動而必明，明而後動，有不空於動之義，故謂噬嗑。此格物致知窮理之學，承上臨卦而來。臨者，二陽而臨四陰，所以進陽採藥也。但藥物有老嫩，火候有時刻，毫髮之差，千里之失，此窮理功夫不可缺也。</p><p>蓋了性了命之學，全在窮理上定優劣，明的一分，行的一分，明的十分，行的十分，或知性而不知命，或知命而不知性，或知有為而不知無為，或知無為而不知有為，或知藥物而不知火候，或知下手而不知結果，凡此皆是窮理不徹，而行持必不通。惟欲動之，須先明之，先明後動，動而無不如意，是以噬嗑用明中之動，有亨道也。明中之動，動必本明，其亨其利，有象治獄。天下難治之事，莫如獄。獄之真情不明，是者為非，非者為是，冒然用刑，殃及無辜，誤傷性命。</p><p>修道如治獄也。辨別真假是非，如治獄之審斷善惡；去假存真，而保性命，如治獄之賞善罰惡，而伸冤屈。人能以治獄之道窮究其實理，則明於心而見於行，儘性至命，未有不亨不利者也。</p><p>初九，剛而不明，冒然前進，進必至咎，是以屢校滅趾，以戒其足，勿妄動。不妄動於初，自不致咎於終。此行道先貴窮理也。</p><p>六二，柔而不剛，見理未真，僅得其膚廓，未得其肯綮，若急欲行之，不但無補於內，而且有傷於外，如噬膚滅鼻矣。鼻所以辨香臭，口食物而鼻先臭之。口不知味，雖鼻能辨，亦屬於無用。幸其柔而中正，見理未真，不敢行持，得以無咎。此窮理未入者也。</p><p>六三，居二之上，識見稍高於二，較二更進一層，如噬臘肉也。肉在膚內，肉至於臘，須剛烈深入而後知味。三雖進益，猶未得真，似是而非，若有妄動，必反招兇，如噬臘肉遇毒矣。然志剛而性柔，不能成事，亦不敗事，雖有小吝，終得無咎。此窮理漸入者也。</p><p>九四，居於明體，在三之上，窮理較三更進一層，如噬乾胏矣。胏為貼骨之肉，絲膜相雜，骨肉相連，又至於乾，不易剝去，若不刻入深進，而不能見真。以象取之，得金矢；以理取之，利艱貞。艱貞之利，不能辨而強辨，深造自得，如用金矢，而無微不入，似是而非之假，可以一概剝去，而得其真。明明朗朗，明於動，而動之無有不吉者。此窮理見真者也。</p><p>六五，居於四上，柔而虛中，窮理較四更進一層，如噬乾肉矣。窮理至四之金矢，是非邪正，判然分明，如乾肉而噬之無味，無容再嚼矣。然雖無味，猶當溫故知新，於已明之理，更下一層功夫，已明而益求其明，必無一毫疑惑，而後篤行之。以象取之得黃金，以理取之為貞厲。黃金者，明而歸中；貞厲者，正而驚懼，虛中驚懼，實見的有些一番道理。明於內而驗於外，無行不合道，無事不得吉。此窮理絕無一疑者也。</p><p>上九，剛而不明，不知辨別實理，誤用聰明，入於旁門，空空一世，終歸泯滅，是以何校滅耳也。目明而耳聰，不能明理，應滅其目，何至來耳？蓋以迷人不明大道者，皆由亂學亂問，聽信盲師，不辨真假，著空執相，每多招兇受害，其禍根在耳。出乎爾旨反乎爾，不明於始，受傷於終，理有可決。此絕不知窮理者也。</p><p>然則窮理功夫，須要剝去一層又一層，直剝到道之骨髓處，無些子疑惑，方是真知灼見。若未到道之骨髓處，猶有隔礙，未雲得真，不可妄動自招其禍。</p><p>噫!縱識硃砂與黑鉛，不知火候也如閒，大都全借修持力，毫髮差殊不結丹。窮理工夫，豈小焉哉!</p>',25)])])}const m=p(s,[["render",n]]);export{d as __pageData,m as default};
